import math


def circle_area(r: float) -> float:
    return math.pi * r * r


def e_const() -> float:
    return math.e


def tau_const() -> float:
    return math.tau


def sine(x: float) -> float:
    return math.sin(x)


def cosine(x: float) -> float:
    return math.cos(x)


def exp_of(x: float) -> float:
    return math.exp(x)


def ln_of(x: float) -> float:
    return math.log(x)


def log10_of(x: float) -> float:
    return math.log10(x)


def log2_of(x: float) -> float:
    return math.log2(x)
